6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
13	import org.springframework.samples.petclinic.rest.function.common.Localities;
14	
15	/**
16	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where
17	 * REGION is the version-2 {@link Localities#identityRegion identity region} (the plain region with
18	 * the fixed {@code V2} tag mixed in, e.g. {@code NSWV2}), FY is the two-digit fiscal year (starting
19	 * 1 July) of the business-day-adjusted {@code registrationDate}, HASH8 is the first eight upper-case
20	 * hex characters of SHA-256 over the {@code V2} tag, the normalized telephone and the last name, and
21	 * CHK is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>} (e.g.
22	 * {@code NSWV2261A2B3C4D7}). Mixing the {@code V2} tag into both the region and the hash guarantees no
23	 * version-1 memberId is ever reproduced. Runs after telephone normalization and
24	 * the registration date default, so the hash is taken over the stored, normalized (E.164) telephone
25	 * and the fiscal year is known.
26	 *
27	 * <p>If the computed memberId collides with an existing owner's {@code memberId}, {@code -<n>} is
28	 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
29	 * receive distinct member ids. Runs before the owner is saved, so it is matched only against owners
30	 * already present.
31	 */
32	public class AssignMemberId {
33	
34	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
35	        String region = Localities.identityRegion(owner.getPostcode(), owner.getCity());
36	        String fy = String.format("%02d", FiscalYear.endingYear(owner.getRegistrationDate()) % 100);
37	        String hash8 = shaHex(
38	                Localities.IDENTITY_VERSION_TAG + owner.getTelephone() + owner.getLastName(), 8);
39	        String core = region + fy + hash8;
40	        String base = core + luhn(core);
41	
42	        Set<String> existing = new HashSet<>();
43	        for (Owner other : ownerRepository.findAll()) {
44	            existing.add(other.getMemberId());
45	        }
46	
47	        String memberId = base;
48	        for (int n = 2; existing.contains(memberId); n++) {
49	            memberId = base + "-" + n;
50	        }
51	        owner.setMemberId(memberId);
52	    }
53	
54	    /**
55	     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
